package com.smartspend.controller;
import com.smartspend.dao.*;import com.smartspend.model.*;import com.smartspend.service.*;import com.smartspend.util.*;import javafx.geometry.*;import javafx.scene.control.*;import javafx.scene.layout.*;import javafx.stage.FileChooser;import java.io.File;import java.time.LocalDate;
public class ReceiptView extends VBox {private final ReceiptService parser=new ReceiptService();private final TransactionService ts=new TransactionService();private final CategoryDAO cd=new CategoryDAO();private final int uid=Session.getUser().getId();private final TextField merchant=UI.input("Merchant"),amount=UI.input("Total amount");private final DatePicker date=new DatePicker(LocalDate.now());private final ComboBox<Category>cat=new ComboBox<>();private final Label status=new Label("No receipt selected.");public ReceiptView(){setPadding(new Insets(5,30,30,30));setSpacing(15);cat.getItems().addAll(cd.findAll());Button choose=UI.button("Choose Receipt Image");choose.setOnAction(e->choose());Button save=UI.button("Save Expense");save.setOnAction(e->save());status.getStyleClass().add("muted");getChildren().addAll(UI.title("Receipt Scanner"),UI.subtitle("Upload → review extracted fields → save. Current fallback is clearly labeled demo mode."),UI.card(choose,status),UI.card(new Label("Extracted Information"),merchant,date,amount,cat,save));}private void choose(){FileChooser f=new FileChooser();f.getExtensionFilters().add(new FileChooser.ExtensionFilter("Images","*.png","*.jpg","*.jpeg"));File file=f.showOpenDialog(getScene().getWindow());if(file!=null){Transaction t=parser.parse(file.toPath());merchant.setText(t.getDescription());status.setText("Demo parser processed: "+file.getName()+". Review the fields before saving.");}}private void save(){try{Category c=cat.getValue();if(c==null)throw new IllegalArgumentException("Choose a category.");Transaction t=new Transaction(0,uid,c.getId(),Double.parseDouble(amount.getText()),"EXPENSE",merchant.getText(),date.getValue(),"Other","Saved from receipt review",c.getName());ts.create(t);UI.alert(getScene().getWindow(),"Saved","Receipt expense saved successfully.");}catch(Exception e){UI.error(getScene().getWindow(),e.getMessage());}}}
